mapper.select:
SELECT ch.id AS chapterId, ch.chapter_name AS chapterName, ch.chapter_order AS chapterOrder, COUNT(n.id) AS uploadCount, SUM(CASE WHEN n.note_status = 2 THEN 1 ELSE 0 END) AS completedCount, SUM(CASE WHEN n.note_status = 1 THEN 1 ELSE 0 END) AS pendingCount, SUM(CASE WHEN n.note_status = 4 THEN 1 ELSE 0 END) AS failedCount FROM ainote_chapter ch LEFT JOIN ainote_note n ON n.chapter_id = ch.id AND n.tenant_id = #{tenantId} AND n.note_status != 3
AND EXISTS ( SELECT 1 FROM ainote_teaching t WHERE t.id = n.teaching_id AND t.tenant_id = #{tenantId} AND t.semester = #{semester} )
WHERE ch.course_id = #{courseId}
AND ch.id = #{chapterId}
GROUP BY ch.id, ch.chapter_name, ch.chapter_order ORDER BY ch.chapter_order

SELECT COUNT(*) FROM ainote_note n
WHERE n.course_id = #{courseId} AND n.tenant_id = #{tenantId} AND n.note_status != 3

    AND EXISTS (
        SELECT 1 FROM ainote_teaching t
        WHERE t.id = n.teaching_id AND t.tenant_id = #{tenantId} AND t.semester = #{semester}
    )

SELECT COUNT(*) FROM ainote_note n
WHERE n.course_id = #{courseId} AND n.tenant_id = #{tenantId} AND n.note_status = 2

    AND EXISTS (
        SELECT 1 FROM ainote_teaching t
        WHERE t.id = n.teaching_id AND t.tenant_id = #{tenantId} AND t.semester = #{semester}
    )

SELECT COUNT(*) FROM ainote_material m
JOIN ainote_note n ON n.id = m.note_id
WHERE n.course_id = #{courseId} AND n.tenant_id = #{tenantId}
  AND n.note_status != 3 AND m.del_flag = 0

    AND EXISTS (
        SELECT 1 FROM ainote_teaching t
        WHERE t.id = n.teaching_id AND t.tenant_id = #{tenantId} AND t.semester = #{semester}
    )

SELECT COUNT(DISTINCT n.student_id) FROM ainote_note n
WHERE n.course_id = #{courseId} AND n.tenant_id = #{tenantId} AND n.note_status != 3

    AND EXISTS (
        SELECT 1 FROM ainote_teaching t
        WHERE t.id = n.teaching_id AND t.tenant_id = #{tenantId} AND t.semester = #{semester}
    )

SELECT m.file_type AS materialType, COUNT(*) AS count
FROM ainote_material m
JOIN ainote_note n ON n.id = m.note_id
WHERE n.course_id = #{courseId} AND n.tenant_id = #{tenantId}
  AND n.note_status != 3 AND m.del_flag = 0

    AND EXISTS (
        SELECT 1 FROM ainote_teaching t
        WHERE t.id = n.teaching_id AND t.tenant_id = #{tenantId} AND t.semester = #{semester}
    )

GROUP BY m.file_type

SELECT n.keywords FROM ainote_note n
WHERE n.course_id = #{courseId} AND n.tenant_id = #{tenantId}
  AND n.note_status != 3 AND n.keywords IS NOT NULL AND n.keywords != ''

    AND EXISTS (
        SELECT 1 FROM ainote_teaching t
        WHERE t.id = n.teaching_id AND t.tenant_id = #{tenantId} AND t.semester = #{semester}
    )
